import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaiDoXe = () => {
    const [selectedSlot, setSelectedSlot] = useState(null);
    const [loading, setLoading] = useState(false);

    // ĐẦU CHỜ BACKEND: Thông tin chi tiết của vị trí đỗ đang được chọn
    // Dữ liệu mẫu sau này từ API sẽ có dạng: { ownerName: "Phan Vinh", room: "101", status: "Đã sử dụng" }
    const [slotDetail, setSlotDetail] = useState(null);

    // Tạo danh sách 40 vị trí đỗ: Dãy A, B, C, D (Mỗi dãy 10 ô)
    const zones = ['A', 'B', 'C', 'D'];
    const allSlots = [];
    zones.forEach(zone => {
        for (let i = 1; i <= 10; i++) {
            allSlots.push(`${zone}-${i.toString().padStart(2, '0')}`);
        }
    });

    // --- TỐI ƯU BACKEND: FETCH THÔNG TIN CHỦ SỞ HỮU ---
    useEffect(() => {
        if (!selectedSlot) return;

        const fetchSlotOwnerInfo = async () => {
            setLoading(true);
            try {
                /* SAU NÀY GẮN API:
                // Backend sẽ dựa vào ID vị trí đỗ để JOIN với bảng Cư dân/Hợp đồng đỗ xe
                const res = await axios.get(`/api/parking/detail/${selectedSlot}`);
                setSlotDetail(res.data); 
                */

                // Tạm thời để trống để bạn thấy trạng thái chờ dữ liệu thực
                setSlotDetail(null);
            } catch (error) {
                console.error("Lỗi truy xuất thông tin bãi đỗ:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchSlotOwnerInfo();
    }, [selectedSlot]);

    return (
        <div style={containerStyle} className="glass-card">

            {/* Header */}
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🅿️ QUẢN LÝ BÃI ĐỖ XE</h2>
            </div>

            <div style={contentWrapperStyle}>

                {/* CỘT TRÁI: DANH SÁCH 40 VỊ TRÍ ĐỖ (Dãy A, B, C, D) */}
                <div className="custom-scrollbar" style={sidebarStyle}>
                    {allSlots.map(slot => (
                        <div key={slot} onClick={() => setSelectedSlot(slot)}
                            style={{ 
                                ...slotItemStyle,
                                background: selectedSlot === slot ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                color: selectedSlot === slot ? '#fff' : '#333',
                            }}>
                            {slot}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT CHỦ SỞ HỮU VỊ TRÍ ĐỖ */}
                <div style={mainContentStyle}>
                    {loading ? (
                        <div style={centerTextStyle}>ĐANG KIỂM TRA DỮ LIỆU VỊ TRÍ {selectedSlot}...</div>
                    ) : selectedSlot ? (
                        <div style={{ animation: 'fadeIn 0.3s', display: 'flex', flexDirection: 'column', height: '100%' }}>

                            {/* Tiêu đề vị trí lớn */}
                            <div style={headerContainer}>
                                <span style={subTitleStyle}>THÔNG TIN VỊ TRÍ ĐỖ</span>
                                <h1 style={slotNumberStyle}>VỊ TRÍ {selectedSlot}</h1>
                            </div>

                            {/* Thông tin chủ sở hữu (Đổ từ Backend) */}
                            <div style={infoContainerStyle}>
                                {slotDetail ? (
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
                                        <InfoRow label="Trạng thái" value={slotDetail.trang_thai} color="#28a745" isTag />
                                        <div style={dividerStyle} />
                                        <InfoRow label="Chủ sở hữu" value={slotDetail.ownerName} bold />
                                        <InfoRow label="Số phòng" value={`Phòng ${slotDetail.room}`} />
                                    </div>
                                ) : (
                                    <div style={emptyStateStyle}>
                                        <div style={{ fontSize: '60px', marginBottom: '20px' }}>🅿️</div>
                                        <h3 style={{ color: '#555' }}>VỊ TRÍ TRỐNG</h3>
                                        <p style={{ color: '#999' }}>Vị trí {selectedSlot} hiện chưa có cư dân nào đăng ký sử dụng.</p>
                                        <button style={btnRegisterStyle}>Đăng ký ngay</button>
                                    </div>
                                )}
                            </div>

                        </div>
                    ) : (
                        <div style={centerTextStyle}>Vui lòng chọn một vị trí đỗ ở bên trái để xem thông tin...</div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

// --- COMPONENT CON CHO UI GỌN GÀNG ---
const InfoRow = ({ label, value, color, bold, isTag }) => (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span style={{ fontSize: '18px', color: '#777' }}>{label}:</span>
        {isTag ? (
            <span style={{ padding: '8px 20px', backgroundColor: '#e6f4ea', color: color, borderRadius: '10px', fontWeight: 'bold', fontSize: '14px' }}>
                {value}
            </span>
        ) : (
            <span style={{ fontSize: '22px', fontWeight: bold ? '900' : '600', color: color || '#333' }}>{value}</span>
        )}
    </div>
);

// --- HỆ THỐNG STYLES ĐỒNG BỘ ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)' };
const headerStyle = { padding: '20px', background: 'rgba(0,0,0,0.2)' };
const contentWrapperStyle = { flex: 1, padding: '20px', display: 'flex', gap: '25px', overflow: 'hidden' };
const sidebarStyle = { width: '220px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '8px', alignContent: 'flex-start', overflowY: 'auto', padding: '15px', backgroundColor: 'rgba(0,0,0,0.3)', borderRadius: '20px' };
const slotItemStyle = { padding: '12px 0', borderRadius: '10px', textAlign: 'center', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s' };
const mainContentStyle = { flex: 1, backgroundColor: '#fff', borderRadius: '30px', padding: '40px', display: 'flex', flexDirection: 'column', color: '#333' };
const headerContainer = { borderBottom: '3px solid #8b5e5e', paddingBottom: '20px', marginBottom: '30px' };
const subTitleStyle = { fontSize: '16px', color: '#8b5e5e', fontWeight: 'bold' };
const slotNumberStyle = { fontSize: '50px', margin: 0, fontWeight: '900' };
const infoContainerStyle = { flex: 1, display: 'flex', flexDirection: 'column' };
const dividerStyle = { height: '1px', background: '#eee', margin: '10px 0' };
const centerTextStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', textAlign: 'center', color: '#ccc', fontStyle: 'italic' };
const emptyStateStyle = { flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center' };
const btnRegisterStyle = { marginTop: '20px', padding: '12px 30px', borderRadius: '12px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' };

export default QuanLyBaiDoXe;
